    Bug 2020139 - Stop sending OpenPGP public key file attachments by default, migrate existing prefs to off. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D285390

diff --git a/mail/extensions/am-e2e/prefs/e2e-prefs.js b/mail/extensions/am-e2e/prefs/e2e-prefs.js
index dc034135f5a..150efbcf5a9 100644
--- a/mail/extensions/am-e2e/prefs/e2e-prefs.js
+++ b/mail/extensions/am-e2e/prefs/e2e-prefs.js
@@ -264,7 +264,7 @@ pref("temp.openpgp.enableExperiments", false);
 // settings

 pref("mail.identity.default.sendAutocryptHeaders", true);
-pref("mail.identity.default.attachPgpKey", true);
+pref("mail.identity.default.attachPgpKey", false);
 pref("mail.identity.default.autoEncryptDrafts", true);
 pref("mail.identity.default.protectSubject", true);

diff --git a/mail/modules/MailMigrator.sys.mjs b/mail/modules/MailMigrator.sys.mjs
index 9be2053d683..79bf3ae8eb5 100644
--- a/mail/modules/MailMigrator.sys.mjs
+++ b/mail/modules/MailMigrator.sys.mjs
@@ -30,7 +30,7 @@ export var MailMigrator = {
   _migrateUI() {
     // The code for this was ported from
     // mozilla/browser/components/nsBrowserGlue.js
-    const UI_VERSION = 58;
+    const UI_VERSION = 59;
     const UI_VERSION_PREF = "mail.ui-rdf.version";
     let currentUIVersion = Services.prefs.getIntPref(UI_VERSION_PREF, 0);

@@ -423,6 +423,12 @@ export var MailMigrator = {
         );
       }

+      if (currentUIVersion < 59) {
+        for (const identity of MailServices.accounts.allIdentities) {
+          identity.attachPgpKey = false;
+        }
+      }
+
       // Migration tasks that may take a long time are not run immediately, but
       // added to the MigrationTasks object then run at the end.
       //
